gging purposes when running the test suite, so it should be kept concise. """ pass class AddFeature(ConfigAction): """ This action defines the given Lit feature when running the test suite. The name of the feature can be a string or a callable, in which case it is called with the configuration to produce the feature name(as a string). """ def __init__(self, name): self._name=name def _getName(self, config): name=self._name(config) if callable(self._name) else self._name if not isinstance(name, str): raise ValueError( "Lit feature did not resolve to a string(got{})".format(name) ) return name def applyTo(self, config): config.available_features.add(self._getName(config)) def pretty(self, config, litParams): return "add Lit feature{}".format(self._getName(config)) class AddFlag(ConfigAction): """ This action adds the given flag to the %{flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{flags}}".format(self._getFlag(config)) class AddFlagIfSupported(ConfigAction): """ This action adds the given flag to the %{flags} substitution, only if the compiler supports the flag. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) if hasCompileFlag(config, flag): config.substitutions=_appendToSubstitution( config.substitutions, "%{flags}", flag ) def pretty(self