gging purposes when running the test suite, so it should be kept concise. """ pass class AddFeature(ConfigAction): """ This action defines the given Lit feature when running the test suite. The name of the feature can be a string or a callable, in which case it is called with the configuration to produce the feature name(as a string). """ def __init__(self, name): self._name=name def _getName(self, config): name=self._name(config) if callable(self._name) else self._name if not isinstance(name, str): raise ValueError( "Lit feature did not resolve to a string(got{})".format(name) ) return name def applyTo(self, config): config.available_features.add(self._getName(config)) def pretty(self, config, litParams): return "add Lit feature{}".format(self._getName(config)) class AddFlag(ConfigAction): """ This action adds the given flag to the %{flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{flags}}".format(self._getFlag(config)) class AddFlagIfSupported(ConfigAction): """ This action adds the given flag to the %{flags} substitution, only if the compiler supports the flag. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) if hasCompileFlag(config, flag): config.substitutions=_appendToSubstitution( config.substitutions, "%{flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{flags}}".format(self._getFlag(config)) class AddCompileFlag(ConfigAction): """ This action adds the given flag to the %{compile_flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable compile flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{compile_flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{compile_flags}}".format(self._getFlag(config)) class AddLinkFlag(ConfigAction): """ This action appends the given flag to the %{link_flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable link flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{link_flags}", flag ) def pretty(self, config, litParams): return "append{} to %{{link_flags}}".format(self._getFlag(config)) class PrependLinkFlag(ConfigAction): """ This action prepends the given flag to the %{link_flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable link flag{}, which is not supported".format(flag) config.substitutions=_prependToSubstitution( config.substitutions, "%{link_flags}", flag ) def pretty(self, config, litParams): return "prepend{} to %{{link_flags}}".format(self._getFlag(config)) class AddOptionalWarningFlag(ConfigAction): """ This action adds the given warning flag to the %{compile_flags} substitution, if it is supported by the compiler. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) if hasCompileFlag(config, "-Werror " +flag): config.substitutions=_appendToSubstitution( config.substitutions, "%{compile_flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{compile_flags}}".format(self._getFlag(config)) class AddSubstitution(ConfigAction): """ This action adds the given substitution to the Lit configuration. The substitution can be a string or a callable, in which case it is called with the configuration to produce the actual substitution(as a string). """ def __init__(self, key, substitution): self._key=key self._getSub=( lambda config: substitution(config) if callable(substitution) else substitution ) def applyTo(self, config): key=self._key sub=self._getSub(config) config.substitutions.append((key, sub)) def pretty(self, config, litParams): return "add substitution{}={}".format(self._key, self._getSub(config)) class Feature(object): """ Represents a Lit available feature that is enabled whenever it is supported. A feature like this informs the test suite about a capability of the compiler, platform, etc. Unlike Parameters, it does not make sense to explicitly control whether a Feature is enabled --it should be enabled whenever it is supported. """ def __init__(self, name, actions=None, when=lambda _: True): """ Create a Lit feature for consumption by a test suite. -name The name of the feature. This is what will end up in Lit's available features if the feature is enabled. This can be either a string or a callable, in which case it is passed the TestingConfig and should generate a string representing the name of the feature. -actions An optional list of ConfigActions to apply when the feature is supported. An AddFeature action is always created regardless of any actions supplied here --these actions are meant to perform more than setting a corresponding Lit feature(e.g. adding compiler flags). If 'actions' is a callable, it is called with the current configuration object to generate the actual list of actions. -when A callable that gets passed a TestingConfig and should return a boolean representing whether the feature is supported in that configuration. For example, this can use `hasCompileFlag` to check whether the compiler supports the flag that the feature represents. If omitted, the feature will always be considered supported. """ self._name=name self._actions=[] if actions is None else actions self._isSupported=when def _getName(self, config): name=self._name(config) if callable(self._name) else self._name if not isinstance(name, str): raise ValueError( "Feature did not resolve to a name that's a string, got{}".format(name) ) return name def getActions(self, config): """ Return the list of actions associated to this feature. If the feature is not supported, an empty list is returned. If the feature is supported, an `AddFeature` action is automatically added to the returned list of actions, in addition to any actions provided on construction. """ if not self._isSupported(config): return[] else: actions=( self._actions(config) if callable(self._actions) else self._actions ) return[AddFeature(self._getName(config))] +actions def pretty(self, config): """ Returns the Feature's name. """ return self._getName(config) def _str_to_bool(s): """ Convert a string value to a boolean. True values are "y", "yes", "t", "true", "on" and "1", regardless of capitalization. False values are "n", "no", "f", "false", "off" and "0", regardless of capitalization. """ trueVals=["y", "yes", "t", "true", "on", "1"] falseVals=["n", "no", "f", "false", "off", "0"] lower=s.lower() if lower in trueVals: return True elif lower in falseVals: return False else: raise ValueError("Got string '{}', which isn't a valid boolean".format(s)) def _parse_parameter(s, type): if type is bool and isinstance(s, str): return _str_to_bool(s) elif type is list and isinstance(s, str): return[x.strip() for x in s.split(",") if x.strip()] return type(s) class Parameter(object): """ Represents a parameter of a Lit test suite. Parameters are used to customize the behavior of test suites in a user controllable way. There are two ways of setting the value of a Parameter. The first one is to pass `--param <KEY>=<VALUE>` when running Lit(or equivalently to set `litConfig.params[KEY]=VALUE` somewhere in the Lit configuration files. This method will set the parameter globally for all test suites being run. The second method is to set `config.KEY=VALUE` somewhere in the Lit configuration files, which sets the parameter only for the test suite(s) that use that `config` object. Parameters can have multiple possible values, and they can have a default value when left unspecified. They can also have any number of ConfigActions associated to them, in which case the actions will be performed on the TestingConfig if the parameter is enabled. Depending on the actions associated to a Parameter, it may be an error to enable the Parameter if some actions are not supported in the given configuration. For example, trying to set the compilation standard to C++23 when `-std=c++23` is not supported by the compiler would be an error. """ def __init__(self, name, type, help, actions, choices=None, default=None): """ Create a Lit parameter to customize the behavior of a test suite. -name The name of the parameter that can be used to set it on the command-line. On the command-line, the parameter can be set using `--param <name>=<value>` when running Lit. This must be non-empty. -choices An optional non-empty set of possible values for this parameter. If provided, this must be anything that can be iterated. It is an error if the parameter is given a value that is not in that set, whether explicitly or through a default value. -type A callable that can be used to parse the value of the parameter given on the command-line. As a special case, using the type `bool` also allows parsing strings with boolean-like contents, and the type `list` will parse a string delimited by commas into a list of the substrings. -help A string explaining the parameter, for documentation purposes. TODO: We should be able to surface those from the Lit command-line. -actions A callable that gets passed the parsed value of the parameter(either the one passed on the command-line or the default one), and that returns a list of ConfigAction to perform given the value of the parameter. All the ConfigAction must be supported in the given configuration. -default An optional default value to use for the parameter when no value is provided on the command-line. If the default value is a callable, it is called with the TestingConfig and should return the default value for the parameter. Whether the default value is computed or specified directly, it must be in the 'choices' provided for that Parameter. """ self._name=name if len(self._name)==0: raise ValueError("Parameter name must not be the empty string") if choices is not None: self._choices=list(choices) if len(self._choices)==0: raise ValueError( "Parameter '{}' must be given at least one possible value".format( self._name ) ) else: self._choices=None self._parse=lambda x: _parse_parameter(x, type) self._help=help self._actions=actions self._default=default def _getValue(self, config, litParams): """ Return the value of the parameter given the configuration objects. """ param=getattr(config, self.name, None) param=litParams.get(self.name, param) if param is None and self._default is None: raise ValueError( "Parameter{} doesn't have a default value, but it was not specified in the Lit parameters or in the Lit config".format( self.name ) ) getDefault=( lambda: self._default(config) if callable(self._default) else self._default ) if param is not None: (pretty, value)=(param, self._parse(param)) else: value=getDefault() pretty="{}(default)".format(value) if self._choices and value not in self._choices: raise ValueError( "Got value '{}' for parameter '{}', which is not in the provided set of possible choices:{}".format( value, self.name, self._choices ) ) return(pretty, value) @property def name(self): """ Return the name of the parameter. This is the name that can be used to set the parameter on the command-line when running Lit. """ return self._name def getActions(self, config, litParams): """ Return the list of actions associated to this value of the parameter. """ (_, parameterValue)=self._getValue(config, litParams) return self._actions(parameterValue) def pretty(self, config, litParams): """ Return a pretty representation of the parameter's name and value. """ (prettyParameterValue, _)=self._getValue(config, litParams) return "{}={}".format(self.name, prettyParameterValue)

