m is None and self._default is None: raise ValueError( "Parameter{} doesn't have a default value, but it was not specified in the Lit parameters or in the Lit config".format( self.name ) ) getDefault=( lambda: self._default(config) if callable(self._default) else self._default ) if param is not None: (pretty, value)=(param, self._parse(param)) else: value=getDefault() pretty="{}(default)".format(value) if self._choices and value not in self._choices: raise ValueError( "Got value '{}' for parameter '{}', which is not in the provided set of possible choices:{}".format( value, self.name, self._choices ) ) return(pretty, value) @property def name(self): """ Return the name of the parameter. This is the name that can be used to set the parameter on the command-line when running Lit. """ return self._name def getActions(self, config, litParams): """ Return the list of actions associated to this value of the parameter. """ (_, parameterValue)=self._getValue(config, litParams) return self._actions(parameterValue) def pretty(self, config, litParams): """ Return a pretty representation of the parameter's name and value. """ (prettyParameterValue, _)=self._getValue(config, litParams) return "{}={}".format(self.name, prettyParameterValue)

