        if not self._isSupported(config):
            return []
        else:
            actions = (
                self._actions(config) if callable(self._actions) else self._actions
            )
            return [AddFeature(self._getName(config))] + actions

    def pretty(self, config):
        """
        Returns the Feature's name.
        """
