gging purposes when running the test suite, so it should be kept concise. """ pass class AddFeature(ConfigAction): """ This action defines the given Lit feature when running the test suite. The name of the feature can be a string or a callable, in which case it is called with the configuration to produce the feature name(as a string). """ def __init__(self, name): self._name=name def _getName(self, config): name=self._name(config) if callable(self._name) else self._name if not isinstance(name, str): raise ValueError( "Lit feature did not resolve to a string(got{})".format(name) ) return name def applyTo(self, config): config.available_features.add(self._getName(config)) def pretty(self, config, litParams): return "add Lit feature{}".format(self._getName(config)) class AddFlag(ConfigAction): """ This action adds the given flag to the %{flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{flags}}".format(self._getFlag(config)) class AddFlagIfSupported(ConfigAction): """ This action adds the given flag to the %{flags} substitution, only if the compiler supports the flag. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) if hasCompileFlag(config, flag): config.substitutions=_appendToSubstitution( config.substitutions, "%{flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{flags}}".format(self._getFlag(config)) class AddCompileFlag(ConfigAction): """ This action adds the given flag to the %{compile_flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable compile flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{compile_flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{compile_flags}}".format(self._getFlag(config)) class AddLinkFlag(ConfigAction): """ This action appends the given flag to the %{link_flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable link flag{}, which is not supported".format(flag) config.substitutions=_appendToSubstitution( config.substitutions, "%{link_flags}", flag ) def pretty(self, config, litParams): return "append{} to %{{link_flags}}".format(self._getFlag(config)) class PrependLinkFlag(ConfigAction): """ This action prepends the given flag to the %{link_flags} substitution. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) assert hasCompileFlag( config, flag ), "Trying to enable link flag{}, which is not supported".format(flag) config.substitutions=_prependToSubstitution( config.substitutions, "%{link_flags}", flag ) def pretty(self, config, litParams): return "prepend{} to %{{link_flags}}".format(self._getFlag(config)) class AddOptionalWarningFlag(ConfigAction): """ This action adds the given warning flag to the %{compile_flags} substitution, if it is supported by the compiler. The flag can be a string or a callable, in which case it is called with the configuration to produce the actual flag(as a string). """ def __init__(self, flag): self._getFlag=lambda config: flag(config) if callable(flag) else flag def applyTo(self, config): flag=self._getFlag(config) if hasCompileFlag(config, "-Werror " +flag): config.substitutions=_appendToSubstitution( config.substitutions, "%{compile_flags}", flag ) def pretty(self, config, litParams): return "add{} to %{{compile_flags}}".format(self._getFlag(config)) class AddSubstitution(ConfigAction): """ This action adds the given substitution to the Lit configuration. The substitution can be a string or a callable, in which case it is called with the configuration to produce the actual substitution(as a string). """ def __init__(self, key, substitution): self._key=key self._getSub=( lambda config: substitution(config) if callable(substitution) else substitution ) def applyTo(self, config): key=self._key sub=self._getSub(config) config.substitutions.append((key, sub)) def pretty(self, config, litParams): return "add substitution{}={}".format(self._key, self._getSub(config)) class Feature(object): """ Represents a Lit available feature that is enabled whenever it is supported. A feature like this informs the test suite about a capability of the compiler, platform, etc. Unlike Parameters, it does not make sense to explicitly control whether a Feature is enabled --it should be enabled whenever it is supported. """ def __init__(self, name, actions=None, when=lambda _: True): """ Create a Lit feature for consumption by a test suite. -name The name of the feature. This is what will e